-- AGENT: block check trùng chuẩn cho composite PK (mẫu quydmgtt) — chỉ
-- import bảng MASTER; bảng chi tiết thường không import qua file này.
-- Đổi name_string_1/name_date_1 -> các cột PK thật; PK_{{table}} = tên
-- PK index thật. PK != 2 cột: sửa điều kiện join + concat khóa.
if @@admin = 0 and @type = '1' begin
  if @@sysDatabaseName.dbo.FastBusiness$System$GetAuthorize(@@admin, @@userID, '{{controller}}', 'Edit') = 0 select @type = '0'
end

declare @message nvarchar(4000), @q nvarchar(4000), @duplicate nvarchar(4000), @irregular nvarchar(4000), @field varchar(32), @irregularChars varchar(128), @r int
select @irregularChars = &IrregularValue;
select @duplicate = case @@language when 'v' then N'Giá trị tại ô <span class="Highlight">%invalidCell</span> đã có trong danh mục.' else 'The value of cell <span class="Highlight">%invalidCell</span> is already exists.' end
select @irregular = case @@language when 'v' then N'Giá trị tại ô <span class="Highlight">%invalidCell</span> có chứa các ký tự: ' + @irregularChars else 'The value of cell <span class="Highlight">%invalidCell</span> contains any of the following characters: ' + @irregularChars  end

-- Check
create index i on @@table (name_string_1)

if @type = '0' delete @@table from @@table a join {{table}} b on a.name_string_1 = b.name_string_1 and a.name_date_1 = b.name_date_1

-- Checking
&Checking;

select a.* into #k from @@table a join {{table}} b with (nolock) on a.name_string_1 = b.name_string_1 and a.name_date_1 = b.name_date_1

if @type = '1' delete @@table where (name_string_1 + convert(varchar(12), name_date_1, 112)) in (select (name_string_1 + convert(varchar(12), name_date_1, 112)) from #k)
--
select @field = 'name_date_1'
if @$mode = 1 begin
  &StartErrorCount;
  select @q = '&InsertErrorTable; select @field, a.stt, ''00003'' from @@table a, @@table b with (index(i)) where a.name_string_1 = b.name_string_1 and a.name_date_1 = b.name_date_1 and a.stt > b.stt
  &w1;@field, ''@@primaryKeyList''&w2;a.stt&w3;''00003''&w4; group by a.stt'
  exec sp_executesql @q, N'@field varchar(32)', @field
  &EndErrorCount;
  &StartErrorCount;
  select @q = '&InsertErrorTable; select @field, a.stt, ''00003'' from @@table a, {{table}} b with (index(PK_{{table}})) where a.name_string_1 = b.name_string_1 and a.name_date_1 = b.name_date_1
  &w1;@field, ''@@primaryKeyList''&w2;a.stt&w3;''00003''&w4; group by a.stt'
  exec sp_executesql @q, N'@field varchar(32)', @field
  &EndErrorCount;
  &StartErrorCount;
  select @q = '&InsertErrorTable; select @field, b.stt, ''00003'' from {{table}} a, @@table b with (index(i)) where a.name_string_1 = b.name_string_1 and a.name_date_1 = b.name_date_1
  &w1;@field, ''@@primaryKeyList''&w2;b.stt&w3;''00003''&w4; group by b.stt'
  exec sp_executesql @q, N'@field varchar(32)', @field
  &EndErrorCount;
end else begin
  select @q = 'select top 1 @r = a.stt from @@table a, @@table b with (index(i)) where a.name_string_1 = b.name_string_1 and a.name_date_1 = b.name_date_1 and a.stt > b.stt'
  exec sp_executesql @q, N'@r int output', @r = @r output&Duplicate;
  select top 1 @r = a.stt from @@table a, {{table}} b with (index(PK_{{table}})) where a.name_string_1 = b.name_string_1 and a.name_date_1 = b.name_date_1&Duplicate;
  select @q = 'select top 1 @r = b.stt from {{table}} a, @@table b with (index(i)) where a.name_string_1 = b.name_string_1 and a.name_date_1 = b.name_date_1'
  exec sp_executesql @q, N'@r int output', @r = @r output&Duplicate;
end

&EndErrorMode;

-- Insert
&Inserting;
-- Update
if @type = '1' begin

  &Updating;
end
